inline bool opaque(int city,int offset) {
  return (pgm_read_byte(masks[city]+offset/8)>>(7-offset%8))&1;
}
inline void draw(Arduino_GFX* display,int city,int x,int y) {
  if(city<0 || city>=cityCount) return;
  uint16_t row[width]; // 48 stack bytes, no heap allocation.
  for(int dy=0;dy<height;++dy) {
    int dx=0;
    while(dx<width) {
      while(dx<width && !opaque(city,dy*width+dx)) ++dx;
      const int start=dx;
      while(dx<width && opaque(city,dy*width+dx)) {
        row[dx-start]=pgm_read_word(pixels[city]+dy*width+dx);++dx;
      }
      if(dx>start) display->draw16bitRGBBitmap(x+start,y+dy,row,dx-start,1);
    }
  }
}
